510	// executionTarget 是 register 与投票两种来源提案在执行路径上的统一视图。
511	type executionTarget struct {
512		state        string
513		timelockEnd  int64
514		actions      []string
515		markExecuted func()
516	}
517	
518	// resolveExecutable 在两种提案表中按编号定位执行目标；不存在返回 nil。
519	func resolveExecutable(state *storedState, id string) *executionTarget {
520		if p, ok := state.Proposals[id]; ok {
521			return &executionTarget{
522				state:        p.State,
523				timelockEnd:  p.TimelockEnd,
524				actions:      p.Actions,
525				markExecuted: func() { p.State = "executed" },
526			}
527		}
528		if vp, ok := state.VoteProposals[id]; ok {
529			return &executionTarget{
530				state:        vp.State,
531				timelockEnd:  vp.TimelockEnd,
532				actions:      vp.Actions,
533				markExecuted: func() { vp.State = "executed" },
534			}
535		}
536		return nil
537	}
