539	// proposalOwners 将两个来源的提案编号映射到状态、时间锁与动作，供凭据重放交叉校验。
540	func proposalOwnerState(state *storedState, id string) (string, int64, []string, bool) {
541		if p, ok := state.Proposals[id]; ok {
542			return p.State, p.TimelockEnd, p.Actions, true
543		}
544		if vp, ok := state.VoteProposals[id]; ok {
545			return vp.State, vp.TimelockEnd, vp.Actions, true
546		}
547		return "", 0, nil, false
548	}
