550	// Execute 按编号执行一项提案。调用方通过 now 提供当前时间。
551	// 只有 passed 状态、now 已达到时间锁且动作非空的提案可以首次执行；
552	// 成功后状态变为 executed 并返回凭据。资格不符、动作格式错误、余额不足、
553	// 金额计算溢出都返回明确原因，整项提案不产生部分转账，也不消耗执行机会。
554	// 已完成提案再次执行（即使 now 不同）直接返回首次成功凭据。
555	func (s *Store) Execute(id string, now int64) (*Receipt, error) {
556		commit, err := s.begin()
557		if err != nil {
558			return nil, err
559		}
560		defer commit()
561	
562		state, err := s.loadLocked()
563		if err != nil {
564			return nil, err
565		}
566		target := resolveExecutable(state, id)
567		if target == nil {
568			return nil, fmt.Errorf("%w: %s", ErrProposalNotFound, id)
569		}
570		if target.state == "executed" {
571			if rcpt := findReceipt(state.Receipts, id); rcpt != nil {
572				return cloneReceipt(rcpt), nil
573			}
574			return nil, fmt.Errorf("%w: executed proposal %s has no receipt", ErrStateCorrupt, id)
575		}
576		if target.state != "passed" {
577			return nil, execReject(fmt.Sprintf("proposal %s is not passed (state=%s)", id, target.state))
578		}
579		if now < target.timelockEnd {
580			return nil, execReject(fmt.Sprintf("timelock not reached for %s: now=%d timelock_end=%d", id, now, target.timelockEnd))
581		}
582		if len(target.actions) == 0 {
583			return nil, execReject(fmt.Sprintf("proposal %s has no actions", id))
584		}
585	
586		// 第一阶段：在副本上按统一转账规则（planTransfers）校验并预演全部
587		// 动作。任何一步失败都直接返回，副本之外的状态不落盘。
588		steps, simTreasury, simBalances, perr := planTransfers(target.actions, state.Treasury, state.Balances)
589		if perr != nil {
590			return nil, perr
591		}
592	
593		// 第二阶段：全部预演成功后构造凭据并一次性原子提交。
594		receipt := &Receipt{
595			ProposalID: id,
596			ExecutedAt: now,
597			Order:      int64(len(state.Receipts)),
598			Actions:    make([]ActionReceipt, 0, len(steps)),
599		}
600		// 同步填上字段原始片段，使“提交前校验”与“打开重放校验”走同一份
601		// executed_at/order 判定时不会把本进程新建的凭据误判为字段缺失。
602		receipt.executedAtRaw, _ = json.Marshal(now)
603		receipt.orderRaw, _ = json.Marshal(receipt.Order)
604		for i, st := range steps {
605			receipt.Actions = append(receipt.Actions, st.actionReceipt(i, target.actions[i]))
606		}
607		state.Treasury = simTreasury
608		state.Balances = simBalances
609		target.markExecuted()
610		state.Receipts = append(state.Receipts, receipt)
611	
612		if err := s.commitLocked(state); err != nil {
613			return nil, err
614		}
615		return cloneReceipt(receipt), nil
616	}
617	
618	func findReceipt(receipts []*Receipt, id string) *Receipt {
619		for _, r := range receipts {
620			if r.ProposalID == id {
621				return r
622			}
623		}
624		return nil
625	}
626	
627	func cloneReceipt(r *Receipt) *Receipt {
628		if r == nil {
629			return nil
630		}
631		copied := *r
632		if r.Actions != nil {
633			copied.Actions = make([]ActionReceipt, len(r.Actions))
634			copy(copied.Actions, r.Actions)
635		}
636		return &copied
637	}
