965	// dupKeyInject 在 balances 对象里注入一个重复键。
966	func dupKeyInject(good []byte) []byte {
967		s := string(good)
968		marker := "\"balances\": {"
969		idx := strings.Index(s, marker)
970		if idx < 0 {
971			// 空 balances 被渲染成 {}，改为含重复键的对象。
972			s = strings.Replace(s, "\"balances\": {}", "\"balances\": {\"x\": 1, \"x\": 2}", 1)
973			return []byte(s)
974		}
975		insertAt := idx + len(marker)
976		return []byte(s[:insertAt] + "\"dup\": 1, " + s[insertAt:])
977	}
