1010		results := make([]error, n)
1011		receipts := make([]*Receipt, n)
1012		start := make(chan struct{})
1013		for i := 0; i < n; i++ {
1014			wg.Add(1)
1015			go func(i int) {
1016				defer wg.Done()
1017				<-start
1018				receipts[i], results[i] = store.Execute("gip-1", int64(100+i))
1019			}(i)
1020		}
1021		close(start)
1022		wg.Wait()
1023		successes := 0
