1257	func itoa(i int) string {
1258		if i == 0 {
1259			return "0"
1260		}
1261		neg := i < 0
1262		if neg {
1263			i = -i
1264		}
1265		var buf [20]byte
1266		pos := len(buf)
1267		for i > 0 {
1268			pos--
1269			buf[pos] = byte('0' + i%10)
1270			i /= 10
1271		}
1272		if neg {
1273			pos--
1274			buf[pos] = '-'
1275		}
1276		return string(buf[pos:])
1277	}
