1949		}
1950	
1951		// 尚未执行的相同内容重试：existed=true，状态仍为 passed。
1952		record, existed, err = store.RegisterProposal("gip-1", 100, []string{"transfer:audits:250", "transfer:legal:5"})
1953		if err != nil || !existed || record.State != "passed" {
1954			t.Fatalf("pending retry existed=%v state=%s err=%v", existed, record.State, err)
1955		}
1956	
1957		// 执行后相同内容重试：existed=true，状态必须是 executed，不得报成 passed。
1958		if _, err := store.Execute("gip-1", 100); err != nil {
1959			t.Fatalf("execute: %v", err)
1960		}
1961		record, existed, err = store.RegisterProposal("gip-1", 100, []string{"transfer:audits:250", "transfer:legal:5"})
1962		if err != nil || !existed {
1963			t.Fatalf("executed retry existed=%v err=%v", existed, err)
1964		}
1965		if record.State != "executed" {
1966			t.Fatalf("executed retry reported state=%q, want executed", record.State)
1967		}
1968		if record.ID != "gip-1" || record.TimelockEnd != 100 ||
1969			!sameActions(record.Actions, []string{"transfer:audits:250", "transfer:legal:5"}) {
1970			t.Fatalf("executed retry record = %+v", record)
1971		}
1972	
1973		// 兼容的 Register 接口对已执行提案的相同内容重试仍返回 existed=true。
1974		if existed, err := store.Register("gip-1", 100, []string{"transfer:audits:250", "transfer:legal:5"}); err != nil || !existed {
1975			t.Fatalf("Register retry after execute existed=%v err=%v", existed, err)
1976		}
1977	
1978		// 已执行提案的内容冲突（时间锁、动作原文、动作顺序）仍然报错。
1979		if _, _, err := store.RegisterProposal("gip-1", 101, []string{"transfer:audits:250", "transfer:legal:5"}); !errors.Is(err, ErrProposalConflict) {
1980			t.Fatalf("timelock conflict after execute err=%v", err)
1981		}
1982		if _, _, err := store.RegisterProposal("gip-1", 100, []string{"transfer:legal:5", "transfer:audits:250"}); !errors.Is(err, ErrProposalConflict) {
1983			t.Fatalf("action order conflict after execute err=%v", err)
1984		}
1985	
1986		// 重试只确认已有提案：状态、余额与首次执行凭据不被改写。
1987		if p, ok, _ := store.Proposal("gip-1"); !ok || p.State != "executed" {
1988			t.Fatalf("proposal state = %+v ok=%v", p, ok)
1989		}
1990		if bal, _ := store.TreasuryBalance(); bal != 745 {
1991			t.Fatalf("treasury = %d, want 745", bal)
1992		}
1993		receipt, ok, err := store.Receipt("gip-1")
1994		if err != nil || !ok || receipt.ExecutedAt != 100 {
1995			t.Fatalf("receipt = %+v ok=%v err=%v", receipt, ok, err)
1996		}
1997	
1998		// 返回的记录是副本：调用方改写不影响状态文件中的记录。
1999		record.State = "mutated"
2000		record.Actions[0] = "mutated"
2001		if p, _, _ := store.Proposal("gip-1"); p.State != "executed" || p.Actions[0] != "transfer:audits:250" {
2002			t.Fatalf("stored record was mutated through returned copy: %+v", p)
2003		}
2004	}
2005	
2006	// TestRegisterRetryVersusExecuteRace：相同内容的登记重试与首次执行同时发生时，
2007	// 响应按两者实际确认的先后反映状态——登记先确认返回 passed，执行先完成返回
2008	// executed；无论哪种结果，字段都必须来自同一条被认可的记录，且重试不产生
2009	// 二次资金变动。
2010	func TestRegisterRetryVersusExecuteRace(t *testing.T) {
2011		store, _ := openTempStore(t, 100000)
2012		defer store.Close()
2013		mustRegister(t, store, "gip-race", 0, "transfer:a:1")
2014	
2015		const n = 64
2016		states := make([]string, n)
2017		existedFlags := make([]bool, n)
2018		var wg sync.WaitGroup
2019		for i := 0; i < n; i++ {
2020			wg.Add(2)
2021			go func(i int) {
2022				defer wg.Done()
2023				record, existed, err := store.RegisterProposal("gip-race", 0, []string{"transfer:a:1"})
2024				if err != nil || !existed {
2025					t.Errorf("retry existed=%v err=%v", existed, err)
2026					return
2027				}
2028				if record.ID != "gip-race" || record.TimelockEnd != 0 ||
2029					!sameActions(record.Actions, []string{"transfer:a:1"}) {
2030					t.Errorf("retry record = %+v", record)
2031					return
2032				}
2033				states[i] = record.State
2034				existedFlags[i] = existed
2035			}(i)
2036			go func() {
2037				defer wg.Done()
2038				_, _ = store.Execute("gip-race", 0)
2039			}()
2040		}
2041		wg.Wait()
2042	
2043		for i, state := range states {
2044			if state != "passed" && state != "executed" {
2045				t.Fatalf("retry %d reported state=%q", i, state)
2046			}
2047			if !existedFlags[i] {
2048				t.Fatalf("retry %d lost existed flag", i)
2049			}
2050		}
2051		// 全部重试结束后提案已执行，资金只扣减一次。
2052		if p, _, _ := store.Proposal("gip-race"); p.State != "executed" {
2053			t.Fatalf("final state = %s", p.State)
2054		}
2055		if bal, _ := store.TreasuryBalance(); bal != 100000-1 {
2056			t.Fatalf("treasury = %d, want %d", bal, 100000-1)
2057		}
2058		if receipts, _ := store.Receipts(); len(receipts) != 1 {
2059			t.Fatalf("receipts = %d, want 1", len(receipts))
2060		}
2061	}
